func sourceTreeFixture(t *testing.T, width int) (GoSourceTreePolicy, GoSourceTreeOptions) {
	t.Helper()
	fixtureHost(t)
	// Independently computed Git vectors, including directory ordering and a
	// nested Gitlink. No tree or commit expectation is generated by the checker.
	tree, commit := "f16108b871e3305754213ec9df0d1a3de01c8a03", "029f3961d7b2a923593848631aa75f38f7d131df"
	if width == 64 {
		tree, commit = "ea499ec00e92688572c6f72834bc7c1b63234a7d94a17f66422556d4e4dea28e", "6f864b38d150c92bf60393e759d623dacb4cc8ba0b7d573d522c8d6d0191266d"
	}
	root, controls := t.TempDir(), t.TempDir()
	data := map[string]string{"a.b": "leaf before subtree\n", "a/x.go": "package fixture\n", "go.mod": "module example.invalid/parent\n\ngo 1.25.0\n", "run.sh": "#!/bin/sh\nexit 0\n"}
	rawCommit := []byte("tree " + tree + "\nauthor Fixture <fixture.invalid> 0 +0000\ncommitter Fixture <fixture.invalid> 0 +0000\n\nSource tree qualification fixture.\n")
	p := GoSourceTreePolicy{Schema: 1, Profile: GoSourceTreeProfile,
		Source:      Source{Repository: "Example/parent", Commit: commit, Tree: tree, Gitlinks: []Gitlink{{"deps/core", "Example/core", strings.Repeat("1", width)}}},
		GoModSHA256: independentSHA([]byte(data["go.mod"])), CommitObject: File{"parent.commit", int64(len(rawCommit)), independentSHA(rawCommit)}}
	for _, name := range []string{"a.b", "a/x.go", "go.mod", "run.sh"} {
		f, mode, perm := filepath.Join(root, filepath.FromSlash(name)), "100644", os.FileMode(0600)
		if name == "run.sh" {
			mode, perm = "100755", 0700
		}
		if os.MkdirAll(filepath.Dir(f), 0700) != nil || os.WriteFile(f, []byte(data[name]), perm) != nil {
			t.Fatal("source fixture write failed")
		}
		p.Files = append(p.Files, SourceFile{name, int64(len(data[name])), independentSHA([]byte(data[name])), mode})
	}
	if os.WriteFile(filepath.Join(controls, "parent.commit"), rawCommit, 0600) != nil {
		t.Fatal("commit control write failed")
	}
	return p, GoSourceTreeOptions{root, controls}
}

func TestGoSourceTreeParentAndSHA256ObjectBindings(t *testing.T) {
	for _, width := range []int{40, 64} {
		t.Run(map[int]string{40: "sha1", 64: "sha256"}[width], func(t *testing.T) {
			p, options := sourceTreeFixture(t, width)
			raw := marshal(t, p)
			r, err := CheckGoSourceTree(raw, independentSHA(raw), options)
			if err != nil || !r.SourceTreeVerified || r.SourceFilesVerified != 4 || r.SourceBytesVerified != 94 || r.GitlinksBound != 1 || r.CommitObjectsVerified != 1 || r.Commit != p.Source.Commit || r.Tree != p.Source.Tree {
				t.Fatalf("complete source tree or Gitlink binding failed: %+v %v", r, err)
			}
			if r.ChildSourceTreesVerified || r.SourceCommitAuthenticated || r.CompilerUseOfTreeProven || r.ReleaseAccepted {
				t.Fatal("source receipt overstates its content-only scope")
			}
			encoded := marshal(t, r)
			if bytes.Contains(encoded, []byte(options.Directory)) || bytes.Contains(encoded, []byte(options.ControlDirectory)) || bytes.Contains(encoded, []byte("fixture.invalid")) {
				t.Fatal("source receipt exposed a physical path or raw commit data")
			}
			if _, err := GoSBOMPolicyProfile(raw); err == nil {
				t.Fatal("standalone source preflight was confused with a Go SBOM policy")
			}
		})
	}
}

func TestGoSourceTreeRejectsPolicySourceGitlinkAndControlChanges(t *testing.T) {
	cases := []struct {
		name   string
		change func(*GoSourceTreePolicy, *GoSourceTreeOptions)
	}{
		{"schema", func(p *GoSourceTreePolicy, _ *GoSourceTreeOptions) { p.Schema = 2 }},
		{"profile", func(p *GoSourceTreePolicy, _ *GoSourceTreeOptions) { p.Profile = GoSourceSBOMProfile }},
		{"repository", func(p *GoSourceTreePolicy, _ *GoSourceTreeOptions) { p.Source.Repository = "../private" }},
		{"empty-gitlinks", func(p *GoSourceTreePolicy, _ *GoSourceTreeOptions) { p.Source.Gitlinks = nil }},
		{"missing-gitlink", func(p *GoSourceTreePolicy, _ *GoSourceTreeOptions) { p.Source.Gitlinks = []Gitlink{} }},
		{"changed-gitlink", func(p *GoSourceTreePolicy, _ *GoSourceTreeOptions) {
			p.Source.Gitlinks[0].Commit = strings.Repeat("2", 40)
		}},
		{"mixed-object-format", func(p *GoSourceTreePolicy, _ *GoSourceTreeOptions) {
			p.Source.Gitlinks[0].Commit = strings.Repeat("1", 64)
		}},
		{"gitlink-case-prefix", func(p *GoSourceTreePolicy, _ *GoSourceTreeOptions) { p.Source.Gitlinks[0].Path = "A/core" }},
		{"gitlink-file-alias", func(p *GoSourceTreePolicy, _ *GoSourceTreeOptions) { p.Source.Gitlinks[0].Path = "go.mod/child" }},
		{"gitlink-directory-alias", func(p *GoSourceTreePolicy, _ *GoSourceTreeOptions) { p.Source.Gitlinks[0].Path = "a" }},
		{"gitlink-metadata", func(p *GoSourceTreePolicy, _ *GoSourceTreeOptions) { p.Source.Gitlinks[0].Path = ".git/core" }},
		{"control-size", func(p *GoSourceTreePolicy, _ *GoSourceTreeOptions) { p.CommitObject.Bytes = MaxDocumentBytes + 1 }},
		{"control-path", func(p *GoSourceTreePolicy, _ *GoSourceTreeOptions) { p.CommitObject.Path = "../no-export" }},
		{"source-byte", func(_ *GoSourceTreePolicy, o *GoSourceTreeOptions) {
			os.WriteFile(filepath.Join(o.Directory, "a.b"), []byte("changed\n"), 0600)
		}},
		{"self-consistent-file-pin", func(p *GoSourceTreePolicy, o *GoSourceTreeOptions) {
			raw := []byte("changed\n")
			os.WriteFile(filepath.Join(o.Directory, "a.b"), raw, 0600)
			p.Files[0].Bytes, p.Files[0].SHA256 = int64(len(raw)), independentSHA(raw)
		}},
		{"missing-file", func(_ *GoSourceTreePolicy, o *GoSourceTreeOptions) { os.Remove(filepath.Join(o.Directory, "a.b")) }},
		{"extra-file", func(_ *GoSourceTreePolicy, o *GoSourceTreeOptions) {
			os.WriteFile(filepath.Join(o.Directory, "extra"), []byte("x"), 0600)
		}},
		{"checked-out-child", func(_ *GoSourceTreePolicy, o *GoSourceTreeOptions) {
			os.MkdirAll(filepath.Join(o.Directory, "deps", "core"), 0700)
		}},
		{"executable-mode", func(_ *GoSourceTreePolicy, o *GoSourceTreeOptions) {
			os.Chmod(filepath.Join(o.Directory, "run.sh"), 0600)
		}},
		{"control-bytes", func(_ *GoSourceTreePolicy, o *GoSourceTreeOptions) {
			os.WriteFile(filepath.Join(o.ControlDirectory, "parent.commit"), []byte("changed"), 0600)
		}},
		{"extra-control", func(_ *GoSourceTreePolicy, o *GoSourceTreeOptions) {
			os.WriteFile(filepath.Join(o.ControlDirectory, "extra"), []byte("x"), 0600)
		}},
		{"source-tree", func(p *GoSourceTreePolicy, _ *GoSourceTreeOptions) { p.Source.Tree = strings.Repeat("2", 40) }},
		{"missing-source-root", func(_ *GoSourceTreePolicy, o *GoSourceTreeOptions) { o.Directory = "" }},
		{"missing-control-root", func(_ *GoSourceTreePolicy, o *GoSourceTreeOptions) { o.ControlDirectory = "" }},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			p, options := sourceTreeFixture(t, 40)
			tc.change(&p, &options)
			raw := marshal(t, p)
			r, err := CheckGoSourceTree(raw, independentSHA(raw), options)
			if err == nil || !reflect.DeepEqual(r, GoSourceTreeResult{}) || strings.Contains(err.Error(), options.ControlDirectory) && options.ControlDirectory != "" {
				t.Fatal("changed source binding accepted, partial receipt returned or runtime location disclosed")
			}
		})
	}
}

func TestGoSourceTreeRequiresIndependentPolicyHashAndStrictJSON(t *testing.T) {
	p, options := sourceTreeFixture(t, 40)
	raw := marshal(t, p)
	for _, expected := range []string{"", strings.Repeat("0", 64), strings.ToUpper(independentSHA(raw))} {
		if result, err := CheckGoSourceTree(raw, expected, options); err == nil || !reflect.DeepEqual(result, GoSourceTreeResult{}) {
			t.Fatal("unselected policy hash was accepted")
		}
	}
	for _, bad := range [][]byte{bytes.Replace(raw, []byte(`"schema":1`), []byte(`"schema":1,"schema":1`), 1), append(append([]byte{}, raw...), []byte(" {}")...), []byte(`{"schema":1,"profile":"git-go-source-tree-v1","unknown":true}`)} {
		if result, err := CheckGoSourceTree(bad, independentSHA(bad), options); err == nil || !reflect.DeepEqual(result, GoSourceTreeResult{}) {
			t.Fatal("ambiguous source policy was accepted")
		}
	}
	var another GoSourceTreePolicy
	if json.Unmarshal(raw, &another) != nil {
		t.Fatal("fixture JSON failed")
	}
	another.Source.Repository = "Other/parent"
	if _, err := CheckGoSourceTree(marshal(t, another), independentSHA(raw), options); err == nil {
		t.Fatal("self-consistent replacement policy bypassed the independent hash")
	}
}
